import time
from abc import ABC, abstractmethod
from functools import wraps

_cache = {}
CACHE_TTL = 60


def cached(ttl=CACHE_TTL):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (func.__name__, args, tuple(sorted(kwargs.items())))
            now = time.time()
            if key in _cache:
                result, timestamp = _cache[key]
                if now - timestamp < ttl:
                    return result
            result = func(*args, **kwargs)
            _cache[key] = (result, now)
            return result
        return wrapper
    return decorator


# --- Route registry (Open/Closed: new routes register themselves) ---

_registry = []  # list of (method, path, handler_func)


def route(method, path):
    """Decorator to register a handler for a method+path combination."""
    def decorator(func):
        _registry.append((method, path, func))
        return func
    return decorator


# --- Handlers (Single Responsibility: one function per action) ---

@route('GET', '/users')
@cached()
def get_users():
    pass


@route('GET', '/posts')
@cached()
def get_posts():
    pass


@route('GET', '/comments')
@cached()
def get_comments():
    pass


@route('POST', '/users')
def create_user(body):
    _cache.clear()
    pass


@route('POST', '/posts')
def create_post(body):
    _cache.clear()
    pass


# --- Router (Dependency Inversion: depends on the registry abstraction) ---

class Router:
    def __init__(self, registry):
        self._routes = {(method, path): handler for method, path, handler in registry}

    def handle(self, req):
        handler = self._routes.get((req.method, req.path))
        if handler is None:
            return 404
        if req.method == 'POST':
            return handler(req.body)
        return handler()


_router = Router(_registry)


def handle_request(req):
    return _router.handle(req)

